CREATE TABLE "vehicle_listings"("id" text PRIMARY KEY,"organization_id" text NOT NULL,"inventory_unit_id" text NOT NULL,"channel" text NOT NULL,"listing_url" text,"external_listing_id" text,"status" text DEFAULT 'Unknown' NOT NULL,"management_mode" text NOT NULL,"responsible_salesperson" text,"last_synced_at" timestamptz,"removal_task_status" text DEFAULT 'Not Needed' NOT NULL,"notes" text,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "vehicle_listings_id_format" CHECK("id"~'^lst_[a-z0-9_-]{6,64}$'),CONSTRAINT "vehicle_listings_status" CHECK("status" IN('Active','Paused','Removed','Unknown')),CONSTRAINT "vehicle_listings_management_mode" CHECK("management_mode" IN('Authorized Integration','Manual')),CONSTRAINT "vehicle_listings_removal_task_status" CHECK("removal_task_status" IN('Not Needed','Open','Completed')),CONSTRAINT "vehicle_listings_same_inventory_fk" FOREIGN KEY("organization_id","inventory_unit_id") REFERENCES "inventory_units"("organization_id","id"));
CREATE UNIQUE INDEX "vehicle_listings_organization_id_unique" ON "vehicle_listings"("organization_id","id");
CREATE UNIQUE INDEX "vehicle_listings_inventory_channel_external_unique" ON "vehicle_listings"("organization_id","inventory_unit_id","channel","external_listing_id");
CREATE INDEX "vehicle_listings_inventory_status_idx" ON "vehicle_listings"("organization_id","inventory_unit_id","status");
ALTER TABLE "vehicle_listings" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "vehicle_listings" FORCE ROW LEVEL SECURITY;
CREATE POLICY "vehicle_listings_current_tenant_all" ON "vehicle_listings" USING("organization_id"=nullif(current_setting('app.organization_id',true),'')) WITH CHECK("organization_id"=nullif(current_setting('app.organization_id',true),''));
